RouteLaneRegion:
class RouteLaneRegion:
    """An interior, equal-lane region sharing the canonical route-stock ledger.

    Longitudinal/off movements below are the accepted movements, not a second
    vehicle population. Outside the explicit region the existing scalar plant
    remains authoritative. Inlet lane shares are a declared frozen approximation.
    """

    def __init__(self, spec, state, cfg, road, observations):
        from evaluation.controllers.offramp_routing import _add
        self.road = road
        self.cells = list(spec['cells'])
        self.groups = int(spec['lanes'])
        self.rates = copy.deepcopy(spec['exchange_rates_per_sec'])
        self.off_access = dict(spec['off_access'])
        self.ramp_access = dict(spec['ramp_access'])
        count = len(state.freeway_density[road])
        from evaluation.controllers.freeway_geometry import cell_lengths_km
        self.lengths = cell_lengths_km(cfg.network, road, count)
        if getattr(cfg.network,'freeway_hadiuzzaman',None):
            raise ValueError('Joint route lanes have not qualified alternate receiving laws')
        if (not self.cells or self.cells != list(range(self.cells[0], self.cells[-1]+1))
                or self.cells[0] < 1 or self.cells[-1] >= count-1
                or any(not math.isclose(cfg.network.freeway_segment_lanes[road][i],self.groups,abs_tol=1e-9,rel_tol=0.) for i in self.cells)
                or self.groups < 2):
            raise ValueError('Joint lane region requires contiguous interior cells of equal physical width')
        if (len(self.rates) != self.groups or any(len(r) != self.groups for r in self.rates)
                or any(not math.isfinite(r) or r < 0 or (g == k and r != 0)
                       for g,row in enumerate(self.rates) for k,r in enumerate(row))):
            raise ValueError('Invalid explicitly calibrated lateral rates')
        runtime = cfg.network.offramp_route_inventory
        expected_off = {o for o,p in runtime['branches'].items() if p['freeway'] == road and p['source_cell'] in self.cells}
        expected_ramp = {r for r,p in runtime['merges'].items() if p['freeway'] == road and p['cell'] in self.cells}
        if set(self.off_access) != expected_off or set(self.ramp_access) != expected_ramp:
            raise ValueError('Every physical branch and merge in the lane region must be mapped')
        if any(type(g) is not int or not 0 <= g < self.groups for g in list(self.off_access.values())+list(self.ramp_access.values())):
            raise ValueError('Invalid branch or merge lane')
        self.stocks = {i:[{} for _ in range(self.groups)] for i in self.cells}
        moments = {i:[0.]*self.groups for i in self.cells}
        inlet = {}
        mapping = {int(k):v for k,v in spec['inlet_lane_to_group'].items()}
        for physical,fw,i,classes in observations:
            if fw != road:
                continue
            if i in self.stocks:
                g = physical['lane_index']-1
                if not 0 <= g < self.groups:
                    raise ValueError('Current vehicle lane outside the declared region')
                _add(self.stocks[i][g], classes)
                moments[i][g] += physical['speed_kph']
            elif i == self.cells[0]-1 and physical['lane_index'] in mapping:
                g = mapping[physical['lane_index']]
                for key,value in classes.items():
                    target = key.rsplit('|',1)[-1]
                    inlet.setdefault(target,[0.]*self.groups)[g] += value
        self.inlet = {key:[n/sum(row) for n in row] for key,row in inlet.items() if sum(row)}
        self.v = {i:[moments[i][g]/sum(row.values()) if sum(row.values()) else state.freeway_speed[road][i]
                     for g,row in enumerate(rows)] for i,rows in self.stocks.items()}
        self.rows = []
        self.receiving_cells = list(spec.get('congested_receiving_cells', []))
        if self.receiving_cells not in ([], [21]):
            raise ValueError('Diagnostic receiving scope is cell21 only')
        self.receiving_rows = []
        self.reciprocal_off = spec.get('reciprocal_off')
        if self.reciprocal_off not in (None, '10483'):
            raise ValueError('Only the verified10483 shared lane is in scope')
        self.junction_rows = []
        self.max_residual = 0.
        self.assert_partition(state)

    def assert_partition(self, state):
        from evaluation.controllers.offramp_routing import _add
        for i,rows in self.stocks.items():
            aggregate = {}
            for row in rows:
                if any(not math.isfinite(x) or x < -1e-8 for x in row.values()):
                    raise ArithmeticError('Joint lane route stock is negative or nonfinite')
                _add(aggregate,row)
            expected = state.offramp_route_inventory_state['cells'][self.road][i]
            error = max([abs(aggregate.get(k,0.)-expected.get(k,0.)) for k in aggregate.keys()|expected.keys()]+[0.])
            self.max_residual = max(self.max_residual,error)
            if error > 1e-7:
                raise ArithmeticError('Lane and canonical route partitions represent different vehicles')

    def ramp_supply(self, ramp, cfg):
        if ramp not in self.ramp_access:
            return math.inf
        i = cfg.network.offramp_route_inventory['merges'][ramp]['cell']
        n = sum(self.stocks[i][self.ramp_access[ramp]].values())
        supply = max(0., cfg.network.rho_max*self.lengths[i]-n)/cfg.simulation.T_f_h
        if i in self.receiving_cells:
            fd = cfg.network.freeway_segment_params[self.road][i]
            critical = fd['rho_crit']; jam = cfg.network.rho_max
            capacity = critical*fd['v_free']*math.exp(-1/fd['metanet_a_m'])
            supply = min(supply,hadi_receiving_vph(n/self.lengths[i],jam,critical,capacity,capacity/(jam-critical),0.))
        return supply

    def plan(self, state, cfg, mainline, route_requests, q_inter, receiving,
             ramp_release, branch_capacity):
        """Modify only faces touching this region; amounts are vehicles per step."""
        from evaluation.controllers.offramp_routing import _add, _classes
        dt = cfg.simulation.T_f_h
        runtime = cfg.network.offramp_route_inventory
        self.before = copy.deepcopy(self.stocks)
        self.oldv = copy.deepcopy(self.v)
        self.next = copy.deepcopy(self.stocks)
        self.n0 = {i:[sum(r.values()) for r in rows] for i,rows in self.before.items()}
        self.free = {i:[max(0.,cfg.network.rho_max*self.lengths[i]-n) for n in ns] for i,ns in self.n0.items()}
        for i in self.receiving_cells:
            fd = cfg.network.freeway_segment_params[self.road][i]
            critical = fd['rho_crit']; jam = cfg.network.rho_max
            capacity = critical*fd['v_free']*math.exp(-1/fd['metanet_a_m'])
            wave = capacity/(jam-critical)
            for g,n in enumerate(self.n0[i]):
                physical = self.free[i][g]
                limit = dt*hadi_receiving_vph(n/self.lengths[i],jam,critical,capacity,wave,0.)
                self.free[i][g] = min(physical,limit)
                self.receiving_rows.append(dict(time_s=state.time_sec,cell=i,lane=g+1,n_veh=n,
                    physical_space_veh=physical,supply_veh=limit,accepted_budget_veh=self.free[i][g]))
        self.merge = {i:[0.]*self.groups for i in self.cells}
        self.incoming = {i:[0.]*self.groups for i in self.cells}
        self.outgoing = {i:[0.]*self.groups for i in self.cells}
        self.off_sent = {}
        self.off_requests = {}
        self.face_classes = {}
        self.off_classes = {}
        for ramp,g in self.ramp_access.items():
            p = runtime['merges'][ramp];i = p['cell'];amount = ramp_release[ramp]*dt
            if amount > self.free[i][g]+1e-7:
                raise ArithmeticError('Accepted merge exceeds its physical lane space')
            self.free[i][g] -= amount;self.merge[i][g] += amount
            _add(self.next[i][g],_classes('expected_merge:'+ramp,p['route_weights']),amount)
        through = {}
        for i,rows in self.before.items():
            through[i] = []
            for g,row in enumerate(rows):
                fraction = min(1.,self.oldv[i][g]*dt/self.lengths[i])
                composition = {}
                for key,n in row.items():
                    target = key.rsplit('|',1)[-1]
                    if target in self.off_access and runtime['branches'][target]['source_cell'] == i:
                        self.off_requests.setdefault(target,[0.]*self.groups)[g] += n*fraction
                    else:
                        composition[key] = n*fraction
                through[i].append(composition)
        for off,requests in self.off_requests.items():
            i = runtime['branches'][off]['source_cell'];g = self.off_access[off]
            amount = min(requests[g],branch_capacity[off]*dt)
            if off == self.reciprocal_off:
                if i != 20 or g != 0 or i+1 not in self.free:
                    raise ValueError('Shared exit must precede cell21 on lane1')
                through_demand = sum(through[i][g].values())
                through_room = self.free[i+1][g]
                factor = min(1.,through_room/through_demand) if through_demand else 1.
                old_amount = amount
                amount = min(amount,requests[g]*factor)
                self.junction_rows.append(dict(time_s=state.time_sec,cell=i,lane=g+1,
                    through_request_veh=through_demand,through_receiving_veh=through_room,
                    off_request_veh=requests[g],off_before_veh=old_amount,off_accepted_veh=amount))
            row = {k:n for k,n in self.before[i][g].items() if k.rsplit('|',1)[-1] == off}
            total = sum(row.values())
            composition = {k:n*amount/total for k,n in row.items()} if total else {}
            self.off_classes[off] = composition
            self.off_sent[off] = [amount if k == g else 0. for k in range(self.groups)]
            _add(self.next[i][g],composition,-1.)
            # Shared-lane FIFO only where the physical exit is accessible.
            factor = amount/requests[g] if requests[g] else 1.
            through[i][g] = {k:n*factor for k,n in through[i][g].items()}
            route_requests[off] = sum(requests)/dt
        for off in self.off_access:
            self.off_classes.setdefault(off,{})
            self.off_sent.setdefault(off,[0.]*self.groups)
            self.off_requests.setdefault(off,[0.]*self.groups)
            route_requests[off] = sum(self.off_requests[off])/dt
        for i in self.cells:
            mainline[i] = sum(sum(r.values()) for r in through[i])/dt
        for i in range(self.cells[0]-1,self.cells[-1]+1):
            if i in self.stocks:
                requests = [(g,g if i+1 in self.stocks else None,dict(row)) for g,row in enumerate(through[i])]
            else:
                old = state.offramp_route_inventory_state['cells'][self.road][i]
                eligible = {k:n for k,n in old.items() if not (k.rsplit('|',1)[-1] in runtime['branches']
                    and runtime['branches'][k.rsplit('|',1)[-1]]['source_cell'] == i)}
                total = sum(eligible.values());requests = []
                for g in range(self.groups):
                    row = {k:n*mainline[i]*dt/total*self.inlet.get(k.rsplit('|',1)[-1],[1./self.groups]*self.groups)[g]
                           for k,n in eligible.items()} if total else {}
                    requests.append((None,g,row))
            budget = self.free[i+1] if i+1 in self.stocks else [receiving[i+1]*dt]
            totals = [0.]*len(budget)
            for g,k,row in requests:
                totals[0 if k is None else k] += sum(row.values())
            accepted = {}
            for g,k,row in requests:
                j = 0 if k is None else k
                factor = min(1.,budget[j]/totals[j]) if totals[j] else 0.
                moved = {key:n*factor for key,n in row.items()}
                _add(accepted,moved)
                amount = sum(moved.values())
                if g is not None:
                    _add(self.next[i][g],moved,-1.);self.outgoing[i][g] += amount
                if k is not None:
                    _add(self.next[i+1][k],moved);self.incoming[i+1][k] += amount
            self.face_classes[i] = accepted
            q_inter[i] = sum(accepted.values())/dt
        # Lateral transport carries exactly the same destination classes and
        # speed moment. Simultaneous requests share old donor stock and space.
        self.exchange_v = {}
        for i,rows in self.next.items():
            old = copy.deepcopy(rows);ns = [sum(r.values()) for r in old]
            matrix = []
            for g,rates in enumerate(self.rates):
                hazard = sum(rates)
                matrix.append([ns[g]*(1.-math.exp(-hazard*dt*3600))*r/hazard if hazard else 0. for r in rates])
            for k in range(self.groups):
                total = sum(row[k] for row in matrix)
                factor = min(1.,max(0.,cfg.network.rho_max*self.lengths[i]-ns[k])/total) if total else 0.
                for g in range(self.groups):matrix[g][k] *= factor
            moment = [n*v for n,v in zip(ns,self.oldv[i])]
            for g,row in enumerate(matrix):
                for k,amount in enumerate(row):
                    if not amount:continue
                    classes = {key:n*amount/ns[g] for key,n in old[g].items()}
                    _add(rows[g],classes,-1.);_add(rows[k],classes)
                    moment[g] -= amount*self.oldv[i][g];moment[k] += amount*self.oldv[i][g]
            self.exchange_v[i] = [moment[g]/sum(row.values()) if sum(row.values())>1e-9 else self.oldv[i][g]
                                  for g,row in enumerate(rows)]
        self.next_v = {}

    def speed(self, i, state, cfg, control, mn, exposure, delta, kappa):
        from evaluation.controllers.freeway_fd import literature_desired_speed
        net = cfg.network;road = self.road;dt = cfg.simulation.T_f_h;values = []
        for g,n in enumerate(self.n0[i]):
            rho = n/self.lengths[i]
            down = self.n0[i+1][g]/self.lengths[i+1] if i+1 in self.n0 else state.freeway_density[road][i+1]
            up = self.oldv[i-1][g] if i-1 in self.oldv else state.freeway_speed[road][i-1]
            command = mn.segment_vsl(control,road,i,cfg)
            active = command < max(cfg.freeway_follower.vsl_set)-.5
            target = mn.effective_desired_speed_kmh(rho,net.v_free,net.rho_crit,command,net.alpha_vsl,active,
                net.metanet_a_m,getattr(net,'vsl_fd_two_branch',False),net.rho_max,float(getattr(net,'rho_crit_two_branch',0.) or 0.))
            target = literature_desired_speed((getattr(net,'freeway_vsl_fd_response',{}) or {}).get(road),cfg,road,i,rho,target,command,active)
            if exposure is not None:target = exposure.target(cfg,road,i,rho,target,command)
            velocity = mn.metanet_speed_update_kmh(self.exchange_v[i][g],up,rho,down,target,dt,self.lengths[i],
                net.metanet_tau_h,mn.select_anticipation_nu(rho,net,command),net.metanet_kappa_veh_km_lane,net.v_min)
            if i == 22:
                from evaluation.controllers.freeway_fd import cell_state_response, state_response_coefficients
                p = net.freeway_segment_params[road][i]
                response = cell_state_response(net,road,i)
                tau,nu = state_response_coefficients(response,self.exchange_v[i][g],target,rho,down,
                    p['rho_crit'],p['metanet_tau_h'],mn.select_anticipation_nu(rho,net,command))
                base_v = self.exchange_v[i][g]
                relaxation = dt/tau*(target-base_v)
                convection = dt/self.lengths[i]*base_v*(up-base_v)
                pressure = -nu*dt/(tau*self.lengths[i])*(down-rho)/(rho+p['metanet_kappa_veh_km_lane'])
                original = max(net.v_min,base_v+relaxation+convection+pressure)
                assert abs(original-velocity)<1e-8, '139 source formula must match actual scalar runtime'
                downstream_v = self.oldv[i+1][g]
                bounded = max(pressure,-max(0.,base_v-downstream_v)) if pressure<0 else pressure
                velocity = max(net.v_min,base_v+relaxation+convection+bounded)
                self.pressure139_rows.append(dict(time_s=state.time_sec+dt*3600,cell=i,lane=g+1,
                    local_v=base_v,downstream_v=downstream_v,rho=rho,downstream_rho=down,
                    old_pressure=pressure,new_pressure=bounded,old_update=original,new_update=velocity))
            if delta > 0 and self.merge[i][g]:
                velocity -= delta*self.merge[i][g]*self.oldv[i][g]/(self.lengths[i]*(rho+kappa))
            requests = sum(row[g] for off,row in self.off_requests.items() if self.off_access[off] == g
                           and cfg.network.offramp_route_inventory['branches'][off]['source_cell'] == i)
            sent = sum(row[g] for off,row in self.off_sent.items() if self.off_access[off] == g
                       and cfg.network.offramp_route_inventory['branches'][off]['source_cell'] == i)
            if requests > sent+1e-9 and n:
                velocity = min(velocity,(self.outgoing[i][g]+sent)*self.lengths[i]/(dt*n))
            values.append(max(net.v_min,velocity))
        self.next_v[i] = values
        counts = [sum(row.values()) for row in self.next[i]]
        return sum(n*v for n,v in zip(counts,values))/sum(counts) if sum(counts) else sum(values)/len(values)

    def commit(self, state, cfg):
        self.stocks = self.next;self.v = self.next_v
        self.assert_partition(state)
        for i,rows in self.stocks.items():
            for g,row in enumerate(rows):
                n = sum(row.values())
                if n > cfg.network.rho_max*self.lengths[i]+1e-7:
                    raise ArithmeticError('Joint lane stock exceeds physical storage')
                self.rows.append(dict(time_s=state.time_sec+cfg.simulation.T_f_h*3600,cell=i,lane=g+1,
                    n_veh=n,v_kmh=self.v[i][g],merge_veh=self.merge[i][g],
                    mainline_in_veh=self.incoming[i][g],mainline_out_veh=self.outgoing[i][g]))

initialize_inventory:
def initialize_inventory(state, cfg, raw, *, lane_partition=None):
    """Partition current vehicles by route, optionally retaining lane groups.

    The caller supplies the physical lane-to-group map for this same snapshot.
    lane_cells mirrors cells by class; it adds no stock. Its transport remains
    guarded until the physical lane allocator supplies accepted transfers.
    """
    if not inventory_enabled(cfg):
        return {}
    from evaluation.controllers.projection_support import complete_records
    from evaluation.controllers.vehicle_routes import complete_vehicle_routes
    from evaluation.controllers.area_freeway_accounting import continuity_vehicle_counts
    runtime = cfg.network.offramp_route_inventory
    observed = complete_vehicle_routes(raw, required=True)
    cells = {fw: [{} for _ in bounds[:-1]] for fw,bounds in runtime['bounds'].items()}
    records = [p for p in complete_records(raw) if str(p['link_no']) in runtime['physical']]
    lane_specs = getattr(cfg.network, 'freeway_route_lane_regions', {}) or {}
    lane_observations = []
    lane_cells = None
    if lane_partition is not None:
        if raw['sim_sec'] != state.time_sec:
            raise ValueError('Lane route partition requires the current state snapshot')
        if not isinstance(lane_partition, dict) or set(lane_partition) != {'groups_per_cell', 'vehicle_group'}:
            raise ValueError('Explicit complete lane partition required')
        dimensions = lane_partition['groups_per_cell']
        assignments = lane_partition['vehicle_group']
        if (not isinstance(dimensions, dict) or set(dimensions) != set(cells) or not isinstance(assignments, dict)
                or set(assignments) != {p['veh_no'] for p in records}):
            raise ValueError('Lane partition must cover all observed freeway vehicles and roads')
        if any(not isinstance(dimensions[fw], list) or len(dimensions[fw]) != len(rows)
               or any(type(n) is not int or n < 1 for n in dimensions[fw])
               for fw,rows in cells.items()):
            raise ValueError('Invalid lane partition cell dimensions')
        lane_cells = {fw: [[{} for _ in range(n)] for n in dimensions[fw]] for fw in cells}
    known = null = 0
    missed = []
    for physical in records:
        fw, position, cell = _position(runtime, physical['link_no'], physical['position_m'])
        route = observed[physical['veh_no']]
        if route['route_decision_no'] is None:
            weights = _future_distribution(runtime, fw, position, retain_route=True)
            prefix = 'observed_null'
            null += 1
        else:
            key = str(route['route_decision_no']) + ':' + str(route['route_no'])
            selected = runtime['routes'].get(key)
            if route['route_decision_type'].upper() != 'STATIC' or selected is None:
                raise ValueError('Observed freeway route is outside the compiled native paths')
            prefix = 'observed_route:' + key
            target = selected['target']
            branch = runtime['branches'].get(target)
            if branch and branch['freeway'] == fw and branch['source_chain_m'] < position:
                # Native can retain a STATIC route after missing its connector.
                # Preserve this observed identity and mass, not a new destination
                # or NULL eligibility. Its forward fate remains unconfirmed even
                # if another decision lies ahead; do not redraw that choice.
                weights = {_MISSED_TARGET + target: 1.}
                missed.append({'veh_no': physical['veh_no'], 'route': key, 'target': target,
                    'freeway': fw, 'cell': cell, 'link_no': physical['link_no'],
                    'position_m': physical['position_m'], 'chain_m': position,
                    'target_source_chain_m': branch['source_chain_m'],
                    'past_target_m': position - branch['source_chain_m'],
                    'physical_link_on_selected_route': str(physical['link_no']) in selected['path']})
            else:
                if str(physical['link_no']) not in selected['path']:
                    raise ValueError('Observed freeway route is outside the compiled native paths')
                weights = _route_distribution(runtime, selected, fw, position, retain_route=True)
            known += 1
        classes = _classes(prefix, weights)
        _add(cells[fw][cell], classes)
        if fw in lane_specs:
            lane_observations.append((physical, fw, cell, classes))
        if lane_cells is not None:
            group = assignments[physical['veh_no']]
            if type(group) is not int or not 0 <= group < len(lane_cells[fw][cell]):
                raise ValueError('Observed vehicle has invalid physical lane group')
            _add(lane_cells[fw][cell][group], classes)
    origins = {fw: _classes('expected_input:' + row['input'], row['route_weights'])
               for fw,row in runtime['inputs'].items()}
    for fw, row in origins.items():
        for key in row:
            row[key] *= float(state.mainline_origin_queue.get(fw, 0.))
    state.offramp_route_inventory_state = {'schema': 'offramp-route-stock/v1', 'cells': cells, 'origins': origins}
    if lane_cells is not None:
        # This is a partition of cells, never additional vehicles. Until the
        # allocator transports both together, advance_inventory fails closed.
        state.offramp_route_inventory_state['lane_cells'] = lane_cells
    if missed:
        state.offramp_route_inventory_state['missed_target_diagnostics'] = {
            'observed_missed_target_veh': len(missed),
            'policy': 'Observed route retained; accepted forward transport only; no branch redraw or normal terminal TD; final-cell stock remains censored'}
        _update_missed_target_diagnostics(state)
    assert_inventory(state, cfg, continuity_vehicle_counts(state, cfg))
    if lane_specs:
        from evaluation.controllers.physical_lane_groups import RouteLaneRegion
        state._route_lane_regions = {fw: RouteLaneRegion(spec, state, cfg, fw, lane_observations) for fw,spec in lane_specs.items()}
    metadata = {'offramp_route_inventory_initial_known_veh': known,
                'offramp_route_inventory_initial_null_veh': null}
    if missed:
        metadata.update(offramp_route_inventory_initial_missed_target_veh=len(missed),
            offramp_route_inventory_initial_missed_targets=missed,
            offramp_route_inventory_missed_target_diagnostics=deepcopy(
                state.offramp_route_inventory_state['missed_target_diagnostics']))
    return metadata

advance_inventory:
def advance_inventory(state, cfg, fw, *, mainline, terminal, offramps, entry,
                      generated, merges, duration_h):
    """Advect the old partition using only flows accepted by the cell allocator."""
    runtime = cfg.network.offramp_route_inventory
    inv = state.offramp_route_inventory_state
    if 'lane_cells' in inv:
        raise ValueError('Lane route partition transport is not yet integrated; aggregate transport would discard lane identity')
    joint = (getattr(state, '_route_lane_regions', {}) or {}).get(fw)
    old = inv['cells'][fw]
    new = [dict(row) for row in old]
    receipts = {target: {} for target,branch in runtime['branches'].items() if branch['freeway']==fw}
    for i, row in enumerate(old):
        through = {}
        targets = defaultdict(dict)
        for key, amount in row.items():
            target = key.rsplit('|',1)[-1]
            if target in runtime['branches'] and runtime['branches'][target]['source_cell'] == i:
                targets[target][key] = amount
            elif i != len(old)-1 or not target.startswith(_MISSED_TARGET):
                through[key] = amount
        if joint is not None and i in joint.face_classes:
            through = joint.face_classes[i]
        movements = [(through, (mainline[i] if i < len(old)-1 else terminal)*duration_h, i+1, None)]
        movements.extend(((joint.off_classes[target] if joint is not None and target in joint.off_classes else values), offramps.get(target,0.)*duration_h, None, target) for target,values in targets.items())
        for composition, amount, receiver, off in movements:
            total = math.fsum(composition.values())
            if amount > total + 1e-7 or amount < -1e-9:
                raise ValueError('Accepted route flow exceeds its class stock')
            if total and amount:
                fraction = min(1., amount/total)
                _add(new[i], composition, -fraction)
                if receiver is not None and receiver < len(old):
                    _add(new[receiver], composition, fraction)
                if off is not None:
                    _add(receipts[off], composition, fraction)
    source = runtime['inputs'][fw]
    origin = inv['origins'][fw]
    _add(origin, _classes('expected_input:' + source['input'], source['route_weights']), generated*duration_h)
    total = math.fsum(origin.values())
    amount = entry*duration_h
    if amount > total + 1e-7:
        raise ValueError('Accepted mainline entry exceeds its source inventory')
    if total and amount:
        admission = {key: value*min(1., amount/total) for key,value in origin.items()}
        _add(origin, admission, -1.)
        _add(new[0], admission)
    for ramp, flow in merges.items():
        source = runtime['merges'][ramp]
        if source['freeway'] == fw:
            _add(new[source['cell']], _classes('expected_merge:' + ramp, source['route_weights']), flow*duration_h)
    inv['cells'][fw] = [{key: max(0., value) for key,value in row.items() if value != 0.} for row in new]
    if joint is not None:
        joint.commit(state, cfg)
    # This is a receipt of already-debited stock, not another population.
    inv.setdefault('last_offramp_receipts', {})[fw] = dict(
        end_sec=state.time_sec+duration_h*3600., ports=receipts)
    _update_missed_target_diagnostics(state)

rollout:
def rollout(self, initial_cells, boundary_steps, overrides=None, initial_origin_queue=None, *, roads=None,
            port_dynamics=None, ramp_dynamics=None, vsl_zone_heads=None, residence_audit=False,
            lane_group_dynamics=None, horizon_sec=450, offramp_inventory=None, route_lane_regions=None):
    """Advance a contiguous forecast (default450s); observe cells only at t0.

    Boundary steps are10s dictionaries with source_demand_vph[road],
    ramp_release_vph[RM_C...], off_capacity_vph[connector], and
    off_split_ratio[connector]. Optional offramp_occupancy_veh supplies
    external receiving-storage boundary support, explicitly not FW states.
    Optional ramp_dynamics replaces only named external ramp releases with
    conserved travelling/head/merge buffers. Each step then requires explicit
    ramp_arrival_vph and ramp_head_service for those ramps. The canonical
    receiving query sees their predicted eligible stock, never future data.
    Optional vsl_zone_heads projects explicit physical actuator intervals onto
    this component's cells. Absent means the existing zone map is unchanged.
    """
    initial = {(r["road"], int(r["cell"])): r for r in initial_cells}
    starts = {float(r["time_s"]) for r in initial_cells}
    if residence_audit and (not port_dynamics or not self.offramp_interval_service):
        raise ValueError('Exact off-ramp residence audit requires interval-service port dynamics')
    if len(starts) != 1 or not boundary_steps:
        raise ValueError("Exactly one observed initial frame and nonempty boundaries required")
    start = next(iter(starts))
    tf = float(self.base.simulation.T_f_sec)
    # Offline response diagnostics can extend the same continuous state.
    # The default and controller horizon remain450s.
    if type(horizon_sec) is not int or horizon_sec<=0 or horizon_sec>750 or horizon_sec%30:
        raise ValueError('Forecast horizon must be a positive30s multiple, at most750s')
    if len(boundary_steps) * tf != horizon_sec:
        raise ValueError("Every rollout must contain its explicit horizon at canonical step")
    for index, row in enumerate(boundary_steps):
        if abs(row["window_start_s"]-start-index*tf)>1e-8 or abs(row["window_end_s"]-start-(index+1)*tf)>1e-8:
            raise ValueError("Boundary windows must be contiguous and begin at the observed cutoff")
    override_by = (overrides or {}).get("by_direction", {})
    cells, flows, details, port_rows = [], [], [], []
    selected_roads = self.roads if roads is None else tuple(roads)
    if self.lane_groups_enabled != (lane_group_dynamics is not None):
        raise ValueError('Lane-group config and explicit observed group state must be supplied together')
    if lane_group_dynamics is not None:
        if (not isinstance(lane_group_dynamics, dict) or not lane_group_dynamics
                or set(lane_group_dynamics)-set(selected_roads)):
            raise ValueError('Invalid explicit lane-group road map')
        from evaluation.controllers.physical_lane_groups import PhysicalLaneGroups
    lane_group_results = {}
    if not selected_roads or set(selected_roads) - set(self.roads):
        raise ValueError("Unknown/empty selected freeway directions")
    route_runtime = None
    if offramp_inventory is not None:
        from evaluation.controllers import offramp_routing as routing
        if (lane_group_dynamics is not None or
                set(offramp_inventory) != {'contract', 'raw'} or
                offramp_inventory['raw']['sim_sec'] != start):
            raise ValueError('Route inventory requires aggregate cells and the same initial snapshot time')
        contract = offramp_inventory['contract']
        if contract['network']['sha256'] != self.geometry['network']['sha256']:
            raise ValueError('Component route inventory belongs to another native network')
        mapping = json.loads(routing._pinned(contract['mapping']))
        route_runtime = routing.compile_inventory(contract, mapping)
        if route_runtime['bounds'] != self.geometry['bounds']:
            raise ValueError('Route inventory and component cell bounds differ')
        for off, spec in self.offramps.items():
            branch = route_runtime['branches'][str(off)]
            if (branch['freeway'], branch['source_cell']) != (spec['road'], spec['from_cell']):
                raise ValueError('Route inventory and physical exit cell differ')
        for ramp, spec in self.ramps.items():
            branch = route_runtime['merges'][ramp]
            if (branch['freeway'], branch['cell']) != (spec['road'], spec['to_cell']):
                raise ValueError('Route inventory and physical merge cell differ')
    if vsl_zone_heads is not None:
        if not isinstance(vsl_zone_heads, dict) or not vsl_zone_heads or set(vsl_zone_heads)-set(self.roads):
            raise ValueError('Unknown or empty explicit VSL zone map')
        for road, heads in vsl_zone_heads.items():
            if (not isinstance(heads, list) or not heads or heads[0] != 0
                    or any(type(x) is not int or not 0 <= x < len(self.base.network.freeway_segment_lanes[road]) for x in heads)
                    or heads != sorted(set(heads))):
                raise ValueError('Explicit VSL heads must be sorted unique cell indices beginning at zero')
    ramp_specs = {}
    local_ramp_step = tf
    meter_cycle = None
    ramp_rows, ramp_metadata = [], {}
    if ramp_dynamics is not None:
        if (ramp_dynamics.get('schema') != 'physical-ramp-boundary/v1'
                or not isinstance(ramp_dynamics.get('ramps'), dict)
                or not ramp_dynamics['ramps']):
            raise ValueError('Unknown or empty physical ramp dynamics contract')
        ramp_specs = ramp_dynamics['ramps']
        if set(ramp_specs) - set(self.ramps):
            raise ValueError('Unknown physical ramp dynamics target')
        local_ramp_step = ramp_dynamics.get('local_step_sec', tf)
        if isinstance(local_ramp_step, bool) or local_ramp_step not in (1., tf):
            raise ValueError('Ramp local step must be1s or the unchanged freeway step')
        if local_ramp_step == 1.:
            meter_cycle = ramp_dynamics.get('meter_cycle_sec')
            if isinstance(meter_cycle, bool) or meter_cycle != self.original_mainline_step_sec:
                raise ValueError('Local ramp cycle must retain the original actuator period')
    if self.ramp_receiving_nodes and (local_ramp_step != 1. or set(self.ramp_receiving_nodes)-set(ramp_specs)):
        raise ValueError('Receiving nodes require their physical lane buffers and local 1s meter dynamics')
    if self.ramp_lane_coupling and (local_ramp_step!=1. or set(self.ramp_lane_coupling)-set(ramp_specs)
            or set(self.ramp_lane_coupling)-set(self.ramp_receiving_nodes)):
        raise ValueError('Lane coupling requires explicit local1s lane buffers and receiving nodes')
    for road in selected_roads:
        cfg = self._config(road, override_by.get(road, {}))
        if vsl_zone_heads is not None and road in vsl_zone_heads:
            adapter.install_freeway_vsl_zones(cfg, {'freeway': {
                'vsl_zone_heads': {road: vsl_zone_heads[road]}}})
        net = cfg.network
        lanes = net.freeway_segment_lanes[road]
        count = len(lanes)
        net.freeway_segments_per_link = count
        lengths = accounting.cell_lengths_km(cfg, road, len(lanes))
        state = TrafficState.initial(cfg)
        state.time_sec = start
        state.freeway_effective_lanes[road] = list(lanes)
        n0 = [float(initial[road, c]["n_veh"]) for c in range(count)]
        state.freeway_density[road] = [n/(lengths[c]*lanes[c]) for c,n in enumerate(n0)]
        state.freeway_speed[road] = [float(initial[road,c]["v_kmh"]) if initial[road,c]["v_kmh"] not in (None, "")
                                     else net.freeway_segment_params[road][c].get("v_free", net.v_free) for c in range(count)]
        state.mainline_origin_queue[road] = float((initial_origin_queue or {}).get(road, 0.0))
        state.urban_link_storage = dict(net.urban_link_storage_veh)
        route_initial = None
        if route_lane_regions is not None:
            if route_runtime is None or lane_group_dynamics is not None or road not in route_lane_regions:
                raise ValueError('Explicit route inventory and no second lane population required')
            net.freeway_route_lane_regions = {road: copy.deepcopy(route_lane_regions[road])}
        if route_runtime is not None:
            runtime = copy.deepcopy(route_runtime)
            runtime['bounds'] = {road: runtime['bounds'][road]}
            runtime['inputs'] = {road: runtime['inputs'][road]}
            runtime['physical'] = {k:v for k,v in runtime['physical'].items() if v[0] == road}
            for key in ('branches', 'decisions', 'merges'):
                runtime[key] = {k:v for k,v in runtime[key].items() if v['freeway'] == road}
            net.offramp_route_inventory = runtime
            route_initial = routing.initialize_inventory(state, cfg, offramp_inventory['raw'])
        joint_lanes = (getattr(state, '_route_lane_regions', {}) or {}).get(road)
        lane_groups = (PhysicalLaneGroups(lane_group_dynamics[road], state, cfg, accounting,
                       exchange_model=self.lane_exchange_model,interruption_gamma=self.lane_interruption_gamma,
                       destination_policy=self.lane_destination_policy,
                       momentum_advection=self.lane_momentum_advection,
                       port_travel=self.lane_port_travel.get(road),
                       position_aware_initial=self.port_initial_positions,
                       upstream_exit_inventory={o:b for o,b in self.upstream_exit_inventory.items()
                                                if self.offramps[o]['road']==road},
                       ramp_conflict_through_inventory=[r for r in self.ramp_conflict_through_inventory if self.ramps[r]['road']==road],
                       branch_partition=[o for o in self.branch_partition if self.offramps[o]['road']==road],
                       partition_exchange=self.partition_exchange and any(self.offramps[o]['road']==road for o in self.branch_partition),
                       partition_speed_context=self.partition_speed_context and any(self.offramps[o]['road']==road for o in self.branch_partition))
                       if lane_group_dynamics and road in lane_group_dynamics else None)
        control = ControlAction.uncontrolled(cfg)
        vsl_audit = None
        if vsl_zone_heads is not None:
            if getattr(net, 'freeway_buffer_segments', 0):
                raise ValueError('Component VSL binding audit requires no external freeway buffer cells')
            vsl_audit = {'alpha_vsl': float(net.alpha_vsl),
                'vsl_max': float(max(cfg.freeway_follower.vsl_set)),
                'cells': [{'cell':i,'samples':0,'command_active_samples':0,
                    'desired_speed_binding_samples':0,'max_desired_speed_reduction_kmh':0.}
                    for i in range(count)]}
        ramp_buffers = {}
        for ramp in net.ramps:
            if ramp not in ramp_specs:
                continue
            buffer_class = LaneResolvedRampBoundary if ramp in self.ramp_receiving_nodes else PhysicalRampBoundary
            buffer = buffer_class(**ramp_specs[ramp],
                **({'lane_exchange_rates_per_sec':self.ramp_lane_exchange[ramp]} if ramp in self.ramp_lane_exchange else {}))
            geometry = self.ramps[ramp]
            if (buffer.connector_id != str(geometry['connector']) or buffer.time_sec != start
                    or abs(buffer.length_m-geometry['length_m']) > 1e-8
                    or buffer.lanes != geometry['lanes']
                    or abs(buffer.spacing_m-net.urban_avg_vehicle_length_m) > 1e-8):
                raise ValueError('Ramp dynamics geometry/time differs from physical port')
            ramp_buffers[ramp] = buffer
            ramp_metadata[ramp] = buffer.metadata()
            if ramp in self.ramp_lane_coupling:
                ramp_metadata[ramp].update(
                    lane_supply='Explicit lane receiving budgets; accepted merges retain their physical target group',
                    lane_to_mainline_group=list(self.ramp_lane_coupling[ramp]))
        stores = {}
        if port_dynamics:
            if port_dynamics.get('schema') != 'physical-off-storage/v1':
                raise ValueError('Unknown port dynamics contract')
            entry_capacity_mode = port_dynamics.get('entry_capacity_mode', 'storage')
            if entry_capacity_mode not in ('storage', 'storage_and_proxy'):
                raise ValueError('Unknown physical off-ramp entry capacity mode')
            if not port_dynamics['occupancy_lane_loss']:
                cfg.freeway_offramp_capacity_drop.enabled = False
            for off in net.off_ramps:
                spec = self.offramps[off]
                if off in self.offramp_lanes:
                    if lane_groups is None:
                        raise ValueError('Physical lane off-ramp requires mainline lane state')
                    access = lane_groups.spec['off_access'][off]
                    if (access['weights'] != [1, 1, 0] or
                            lane_groups.widths[access['cell']][:2] != [1, 1]):
                        raise ValueError('Off-ramp group-to-lane continuity changed')
                    stores[off] = LaneResolvedDelayedPort(spec['storage_capacity_veh'], spec['length_m'],
                        port_dynamics['travel_speed_kmh'][off], port_dynamics['initial_cohorts'][off], start,
                        port_dynamics['lane_exchange_rates_per_sec'][off])
                    continue
                stores[off] = DelayedPort(spec['storage_capacity_veh'], spec['length_m'],
                    port_dynamics['travel_speed_kmh'][off], port_dynamics['initial_cohorts'][off], start,
                    interval_service=self.offramp_interval_service,
                    entry_accel_mps2=self.offramp_entry_speed.get(off))
        bucket = {c: {"downstream_crossings": 0.0, "source_admissions": 0.0,
                      "ramp_merges": 0.0, "off_departures": 0.0, "terminal_exits": 0.0} for c in range(count)}
        projections = speed_projections = 0
        residual_max = 0.0
        freeway_residence = requested_source = accepted_source = 0.0
        literature_counts = {}
        jam_exceedances = 0
        density_above_critical = negative_count = 0
        maximum_density_ratio = 0.0
        for step in boundary_steps:
            t = float(step["window_start_s"])
            off_entry_speeds = {off:state.freeway_speed[road][net.off_ramp_segment_index[off]]
                                for off in stores if off in self.offramp_entry_speed}
            if 'vsl_commands' in step:
                control.vsl.update(step['vsl_commands'])
            releases = {r: float(step["ramp_release_vph"][r]) for r in net.ramps if r not in ramp_buffers}
            caps = {o: float(step["off_capacity_vph"][o]) for o in net.off_ramps}
            net.off_ramp_split_ratio = {o: float(step["off_split_ratio"][o]) for o in net.off_ramps}
            occupancy = step.get("offramp_occupancy_veh", {})
            junction_inputs={}
            if self.aggregate_merge_speed:
                if lane_groups is not None or not set(net.ramps)<=set(ramp_specs):
                    raise ValueError('Aggregate merge inlet speed requires aggregate cells and ramp speed sources')
                junction_inputs['junction_ramp_speeds']={r:ramp_specs[r].get(
                    'posthead_travel_speed_kmh',ramp_specs[r]['travel_speed_kmh']) for r in net.ramps}
            response=(getattr(net,'freeway_port_response',{}) or {}).get(road)
            if response:
                if lane_groups is None or set(stores)!=set(net.off_ramps):
                    raise ValueError('Junction responses require conserved lane groups and off stores')
                snapshots={}
                for off,store in stores.items():
                    spec=self.offramps[off];access=lane_groups.spec['off_access'][off]
                    density=store.stock/(spec['length_m']/1000*spec['lanes'])
                    bygroup=[density if w else 0. for w in access['weights']]
                    if isinstance(store,LaneResolvedDelayedPort):
                        bygroup=[p.stock/(spec['length_m']/1000) for p in store.lanes]+[0.]
                    snapshots[off]=dict(n_veh=store.stock,capacity_veh=store.capacity,density_by_group=bygroup)
                junction_inputs['offramp_start_state']=snapshots
                if response['merge_speed']:
                    if not set(net.ramps)<=set(ramp_specs):raise ValueError('All ramp travel speeds required')
                    junction_inputs['junction_ramp_speeds']={r:spec.get('posthead_travel_speed_kmh',spec['travel_speed_kmh'])
                                                           for r,spec in ramp_specs.items() if r in net.ramps}
            group_caps = {}
            for off in net.off_ramps:
                storage = net.off_ramp_storage_link[off]
                if off in stores:
                    store = stores[off]
                    if isinstance(store, LaneResolvedDelayedPort):
                        services = step['off_lane_drain_vph'][off]
                        if abs(sum(services)-step['off_drain_vph'][off]) > 1e-7:
                            raise ValueError('Lane drainage must preserve the existing total boundary service')
                        store.release(t, tf, services)
                        group_caps[off] = [max(0., p.capacity-p.stock)*3600/tf for p in store.lanes]+[0.]
                    else:
                        store.release(t, tf, float(step['off_drain_vph'][off]))
                    state.urban_link_storage[storage] = max(0., store.capacity-store.stock)
                    storage_rate = max(0., store.capacity-store.stock)*3600/tf
                    # Keep the old entry-rate proxy only in this explicit
                    # ablation: otherwise changing inventory also removes
                    # that independent cap and obscures the cause of gain.
                    caps[off] = (min(caps[off], storage_rate)
                        if entry_capacity_mode == 'storage_and_proxy' else storage_rate)
                elif off in occupancy:
                    state.urban_link_storage[storage] = max(0.0, net.urban_link_storage_veh[storage] - float(occupancy[off]))
            demand = DemandStep({road: float(step["source_demand_vph"][road])}, {}, {})
            interval_ramp_rows = []
            ramp_group_releases = {}
            if ramp_buffers and local_ramp_step == 1.:
                # Supply is queried once from the t-start freeway state.
                # Scratch availability prevents today's post-head stock from
                # being mistaken for the receiving CAPACITY. It creates no
                # live vehicles or accepted-flow ledger entries.
                supply_state = copy.copy(state)
                supply_state.ramp_queue = dict(state.ramp_queue)
                dt_h = cfg.simulation.T_f_h
                for ramp in ramp_buffers:
                    cap = net.ramp_capacity_veh_h[ramp]
                    supply_state.ramp_queue[ramp] = math.nextafter(cap*dt_h, math.inf)
                    control.ramp_metering[ramp] = cap
                selected, _ = accounting._mn.compute_ramp_release_flows(
                    supply_state, control, demand, cfg, include_current_arrivals=False)
                for ramp, buffer in ramp_buffers.items():
                    budget_rate = float(selected[ramp])
                    canonical_budget_rate = budget_rate
                    if joint_lanes is not None:
                        budget_rate = min(budget_rate, joint_lanes.ramp_supply(ramp,cfg))
                    density_supply = None
                    if self.ramp_receiving_nodes.get(ramp, {}).get('density_supply') == 'origin_capacity':
                        density_supply = ramp_origin_density_supply_vph(state, control, cfg, ramp)
                        budget_rate = min(budget_rate, density_supply)
                    lane_mapping=self.ramp_lane_coupling.get(ramp)
                    lane_budgets=None
                    if lane_mapping is not None:
                        if not isinstance(buffer,LaneResolvedRampBoundary) or lane_groups is None:
                            raise ValueError('Lane coupling requires lane-resolved ramp buffers')
                        conditions=lane_groups.ramp_lane_conditions(ramp,lane_mapping,cfg)
                        lane_budgets=[min(budget_rate/buffer.lanes,r['space_vph']) for r in conditions]
                    elif lane_groups is not None:
                        budget_rate = min(budget_rate, lane_groups.ramp_supply(ramp, cfg))
                    node_audit = None
                    if lane_budgets is not None:
                        spec=self.ramp_receiving_nodes.get(ramp)
                        if spec is not None:
                            gap_rates=[gap_acceptance_supply_vph(r['conflicting_vph'],spec['critical_gap_sec'],spec['followup_sec']) for r in conditions]
                            lane_budgets=[min(q,gap) for q,gap in zip(lane_budgets,gap_rates)]
                        budget_rate=math.fsum(lane_budgets)
                        node_audit={'physical_lane_coupling':True,'lane_conditions':conditions,
                            'canonical_aggregate_budget_vph':canonical_budget_rate,
                            'receiving_budget_vph_by_lane':list(lane_budgets),
                            'lane_to_mainline_group':list(lane_mapping)}
                    elif ramp in self.ramp_receiving_nodes:
                        spec = self.ramp_receiving_nodes[ramp]
                        upstream = net.ramp_merge_segment_index[ramp]-1
                        if upstream < 0:
                            raise ValueError('Receiving-node model requires an upstream freeway cell')
                        # Exclude traffic leaving before the physical merge.
                        split = sum(net.off_ramp_split_ratio[o] for o in net.off_ramps
                                    if net.off_ramp_segment_index[o] == upstream)
                        if not 0. <= split <= 1.:
                            raise ValueError('Invalid upstream off-ramp split sum')
                        conflicting = state.freeway_density[road][upstream]*state.freeway_speed[road][upstream]*(1.-split)
                        if lane_groups is not None:
                            conflicting = lane_groups.conflict_vph_per_lane(ramp)
                        per_lane = gap_acceptance_supply_vph(conflicting, spec['critical_gap_sec'], spec['followup_sec'])
                        node_audit = {'conflicting_vph_per_lane': conflicting,
                            'upstream_cell': upstream, 'off_split_removed': split,
                            'gap_supply_vph_per_lane': per_lane,
                            'unlimited_node_canonical_budget_vph': budget_rate,
                            'lane_flow_assumption': 'Upstream cell mean per lane after off-ramp split'}
                        if lane_groups is not None:
                            node_audit['lane_flow_assumption'] = 'Physical merge target lane-group flow'
                            node_audit.pop('upstream_cell')
                            node_audit['conflict_sample_cell'] = net.ramp_merge_segment_index[ramp]
                            node_audit['off_split_removed'] = 0.
                            node_audit['unlimited_node_canonical_budget_vph'] = canonical_budget_rate
                            node_audit['target_group_storage_limited_budget_vph'] = budget_rate
                        budget_rate = min(budget_rate, buffer.lanes*per_lane)
                    if density_supply is not None:
                        node_audit['origin_density_supply_vph'] = density_supply
                        node_audit['unlimited_node_canonical_budget_vph'] = canonical_budget_rate
                    if not math.isfinite(budget_rate) or budget_rate < 0:
                        raise ValueError('Invalid canonical ramp receiving budget')
                    arrival_vph = float(step['ramp_arrival_vph'][ramp])
                    if not math.isfinite(arrival_vph) or arrival_vph < 0:
                        raise ValueError('Ramp approach requests must be finite and nonnegative')
                    head_service = self._head_service(ramp, step['ramp_head_service'][ramp], meter_cycle)
                    receipt = buffer.advance_local_interval(start_sec=t, duration_sec=tf,
                        cycle_sec=meter_cycle, receiving_budget_veh=budget_rate*dt_h,
                        **({'posthead_speed_kmh':ramp_posthead_speed_kmh(state,cfg,ramp,buffer.posthead_travel_speed_kmh)}
                           if self.ramp_receiving_nodes.get(ramp, {}).get('posthead_speed') == 'merge_cell_cap' else {}),
                        **({'allow_partial_cycle':True} if tf!=meter_cycle else {}),
                        request_arrivals_veh=arrival_vph*dt_h,
                        request_arrivals_by_second=step.get('ramp_arrival_profile',{}).get(ramp),
                        **({'request_arrivals_by_lane_second':step['ramp_arrival_lane_profile'][ramp]}
                           if ramp in step.get('ramp_arrival_lane_profile',{}) else {}),
                        **({'receiving_budget_by_lane_veh':[q*dt_h for q in lane_budgets]} if lane_budgets is not None else {}),
                        **head_service)
                    accepted = receipt['accepted_merge_veh']
                    q = accepted/dt_h
                    coupling_roundoff = q*tf/3600.-accepted
                    if abs(coupling_roundoff) > 1e-8:
                        raise ArithmeticError('Ramp/freeway merge interface roundoff exceeds tolerance')
                    receipt.update(road=road, ramp=ramp,
                        canonical_receiving_budget_vph=budget_rate,
                        applied_merge_vph=q, merge_interface_roundoff_veh=coupling_roundoff)
                    if node_audit is not None:
                        receipt['receiving_node'] = node_audit
                    interval_ramp_rows.append(receipt)
                    releases[ramp] = q
                    if lane_mapping is not None:
                        rates=[0.]*len(lane_groups.n[net.ramp_merge_segment_index[ramp]])
                        for group,lane_receipt in zip(lane_mapping,receipt['lane_receipts']):
                            rates[group]+=lane_receipt['accepted_merge_veh']/dt_h
                        if abs(sum(rates)-q)>1e-7:raise ArithmeticError('Lane ramp/mainline interface mismatch')
                        ramp_group_releases[ramp]=rates
                        receipt['applied_group_merge_vph']=list(rates)
                    state.ramp_queue[ramp] = receipt['end']['merge_ready_veh']
            elif ramp_buffers:
                for ramp, buffer in ramp_buffers.items():
                    eligible = buffer.begin_interval(t, tf)['eligible_merge_veh']
                    state.ramp_queue[ramp] = eligible
                    # The signal has already limited head crossing. Vehicles
                    # downstream of it retain only the canonical merge cap.
                    control.ramp_metering[ramp] = net.ramp_capacity_veh_h[ramp]
                selected, _ = accounting._mn.compute_ramp_release_flows(
                    state, control, demand, cfg, include_current_arrivals=False)
                dt_h = cfg.simulation.T_f_h
                for ramp, buffer in ramp_buffers.items():
                    q = float(selected[ramp])
                    eligible = state.ramp_queue[ramp]
                    raw_amount = q*dt_h
                    if not math.isfinite(q) or q < 0 or raw_amount > eligible+1e-8:
                        raise ValueError('Canonical ramp merge exceeds eligible stock')
                    # Record, rather than conceal, rate/vehicle roundoff. The
                    # exact adjusted rate is used by the freeway and buffer.
                    while q*dt_h > eligible:
                        q = math.nextafter(q, 0.0)
                    amount = q*dt_h
                    buffer.commit_merge(amount)
                    service = step['ramp_head_service'][ramp]
                    buffer.apply_head_service(**service)
                    arrival_vph = float(step['ramp_arrival_vph'][ramp])
                    if not math.isfinite(arrival_vph) or arrival_vph < 0:
                        raise ValueError('Ramp approach requests must be finite and nonnegative')
                    receipt = buffer.finish_interval(arrival_vph*dt_h)
                    receipt.update(road=road, ramp=ramp,
                        canonical_selected_merge_vph=float(selected[ramp]),
                        applied_merge_vph=q, merge_roundoff_adjustment_veh=raw_amount-amount)
                    interval_ramp_rows.append(receipt)
                    releases[ramp] = q
                    state.ramp_queue[ramp] = receipt['end']['merge_ready_veh']
            before = accounting.continuity_vehicle_counts(state, cfg)[road]
            stocks = {"freeway:" + road: {"inside": sum(before)},
                      "origin:" + road: {"outside": state.mainline_origin_queue[road]},
                      **{"merge_pending:" + r: {"outside": q*tf/3600} for r,q in releases.items()}}
            trace = ModelAreaLedger(stocks, capture_response=True)
            trace.begin_response_step("freeway", t, t+tf)
            trace.expect_constraint_coverage("freeway_allocator")
            state._control_area_ledger = trace
            desired_speed = accounting._mn.effective_desired_speed_kmh
            observed_desired = []
            if vsl_audit is not None:
                # Observe the actual call after its segment context is armed.
                # The second pure FD evaluation disables only the speed cap;
                # its result is diagnostic and never enters the transition.
                def record_desired(*args, **kwargs):
                    value = desired_speed(*args, **kwargs)
                    if kwargs or len(args) != 10:
                        raise ValueError('Unexpected desired-speed call contract')
                    baseline_args = list(args)
                    baseline_args[5] = False
                    baseline_value = desired_speed(*baseline_args)
                    observed_desired.append((bool(args[5]), float(value), float(baseline_value)))
                    return value
                accounting._mn.effective_desired_speed_kmh = record_desired
            try:
                transition = lane_groups.advance if lane_groups is not None else accounting._freeway_substep_events
                residence, diag = transition(state, control, demand, cfg,
                    offramp_capacity_veh_h=caps, ramp_release_veh_h=releases,
                    **junction_inputs,
                    **({'offramp_group_capacity_veh_h': group_caps} if group_caps else {}),
                    **({'ramp_group_release_veh_h': ramp_group_releases} if ramp_group_releases else {}),
                    ramp_release_diagnostics={"total_no_meter_flow": sum(releases.values()), "mean_ramp_receiving_factor": 1.0},
                    update_ramp_queues=False, include_ramp_queue_ttt=False)
            finally:
                if vsl_audit is not None:
                    accounting._mn.effective_desired_speed_kmh = desired_speed
            if vsl_audit is not None:
                if joint_lanes is not None:
                    grouped=[]; cursor=0
                    for i in range(count):
                        size=1+(joint_lanes.groups if i in joint_lanes.cells else 0)
                        values=observed_desired[cursor:cursor+size]
                        if len(values)!=size: raise ValueError('Missing local lane desired speed')
                        used=values[1:] if size>1 else values
                        grouped.append(max(used,key=lambda x:x[2]-x[1]));cursor+=size
                    if cursor!=len(observed_desired): raise ValueError('Extra local lane desired speed')
                    observed_desired=grouped
                if lane_groups is not None:
                    grouped = []
                    cursor = 0
                    for i,ws in enumerate(lane_groups.widths):
                        size=len(ws)*(2 if i in lane_groups.partitions else 1)
                        values = observed_desired[cursor:cursor+size]
                        if len(values) != size:
                            raise ValueError('Missing lane-group desired-speed observation')
                        # Preserve the cell audit schema; report the maximum
                        # actual group cap effect rather than averaging it away.
                        grouped.append(max(values, key=lambda x:x[2]-x[1]))
                        cursor += size
                    if cursor != len(observed_desired):
                        raise ValueError('Extra lane-group desired-speed observation')
                    observed_desired = grouped
                if len(observed_desired) != count:
                    raise ValueError('Missing or extra component desired-speed observations')
                for audit, (active, value, baseline_value) in zip(vsl_audit['cells'], observed_desired):
                    reduction = max(0., baseline_value-value)
                    audit['samples'] += 1
                    audit['command_active_samples'] += int(active)
                    audit['desired_speed_binding_samples'] += int(reduction > 1e-9)
                    audit['max_desired_speed_reduction_kmh'] = max(audit['max_desired_speed_reduction_kmh'], reduction)
            state.time_sec = t+tf
            if self.literature is not None:
                for key in ('literature_receiving_limited_cells','literature_command_cells',
                            'literature_drop_changes_receiving_cells','literature_actual_limited_boundaries'):
                    literature_counts[key] = literature_counts.get(key,0.)+diag[key]
            ramp_rows.extend(interval_ramp_rows)
            freeway_residence += residence
            requested_source += demand.freeway_mainline[road]*tf/3600
            actual = {"mainline": [0.0]*count, "off": [0.0]*count, "ramp": [0.0]*count, "entry": 0.0}
            for row in trace._response["resource_allocations"]:
                kind, value = row["kind"], row["accepted_total_veh"]
                if kind == "freeway_mainline_sending":
                    actual["mainline"][int(row["resource"].rsplit(":",1)[1])] = value
                elif kind == "freeway_terminal_sending":
                    actual["mainline"][-1] = value
                elif kind == "freeway_entry_request":
                    actual["entry"] = value
                elif kind == "freeway_offramp_sending":
                    actual["off"][net.off_ramp_segment_index[row["resource"]]] += value
                    if row['resource'] in stores:
                        lane_args = ({'lane_amounts': lane_groups.last_off_sent[row['resource']][:2]}
                            if isinstance(stores[row['resource']], LaneResolvedDelayedPort) else {})
                        stores[row['resource']].accept(t+tf, value,
                            entry_speed_kmh=off_entry_speeds.get(row['resource']), **lane_args)
            for off, store in stores.items():
                port_rows.append({'time_s': t+tf, 'road': road, 'connector': off,
                    'n_veh': store.stock, 'ready_veh': store.ready,
                    'admitted_veh': store.admitted, 'departed_veh': store.departed,
                    'conservation_residual_veh': store.stock-store.initial-store.admitted+store.departed})
                if isinstance(store, LaneResolvedDelayedPort):
                    port_rows[-1]['lanes'] = [{'n_veh':p.stock,'ready_veh':p.ready,
                        'departed_veh':p.departed,'admitted_veh':p.admitted,
                        'internal_in_veh':p.internal_in,'internal_out_veh':p.internal_out} for p in store.lanes]
            for ramp, q in releases.items():
                actual["ramp"][net.ramp_merge_segment_index[ramp]] += q*tf/3600
            after = accounting.continuity_vehicle_counts(state,cfg)[road]
            accepted_source += actual['entry']
            jam_exceedances += sum(rho > net.rho_max+1e-9 for rho in state.freeway_density[road])
            density_above_critical += int(diag['density_exceedance_count'])
            negative_count += sum(rho < -1e-9 for rho in state.freeway_density[road])
            maximum_density_ratio = max(maximum_density_ratio,max(state.freeway_density[road])/net.rho_max)
            for c in range(count):
                incoming = actual["entry"] if c == 0 else actual["mainline"][c-1]
                expected = before[c]+incoming+actual["ramp"][c]-actual["off"][c]-actual["mainline"][c]
                residual_max = max(residual_max, abs(after[c]-expected))
                bucket[c]["downstream_crossings"] += actual["mainline"][c] if c < count-1 else 0.0
                bucket[c]["terminal_exits"] += actual["mainline"][c] if c == count-1 else 0.0
                bucket[c]["source_admissions"] += actual["entry"] if c == 0 else 0.0
                bucket[c]["ramp_merges"] += actual["ramp"][c]
                bucket[c]["off_departures"] += actual["off"][c]
            projections += int(diag["density_projection_count"])
            speed_projections += int(diag["speed_projection_count"])
            if abs((t+tf-start)/30-round((t+tf-start)/30)) < 1e-8:
                for c,n in enumerate(after):
                    physical_area = float(self.geometry_cells[road,c]["lane_km"])
                    cells.append({"time_s": t+tf, "road":road,"cell":c,"n_veh":n,
                        "rho_veh_per_km_lane":n/physical_area,"rho_canonical":state.freeway_density[road][c],
                        "v_kmh":state.freeway_speed[road][c],"effective_lanes":state.freeway_effective_lanes[road][c]})
                    flows.append({"window_start_s":t+tf-30,"window_end_s":t+tf,"road":road,"cell":c,**bucket[c]})
                bucket = {c:dict.fromkeys(bucket[c],0.0) for c in range(count)}
        details.append({"road":road,"start_s":start,"end_s":start+horizon_sec,"density_projection_count":projections,
            "speed_projection_count":speed_projections,"continuity_residual_max_veh":residual_max,
            "jam_density_exceedance_count":jam_exceedances,"model_residence_10s_veh_h":freeway_residence,
            "canonical_density_above_critical_count":density_above_critical,"negative_density_count":negative_count,
            "maxdensity_ratio":maximum_density_ratio,
            "requested_source_veh":requested_source,"accepted_source_veh":accepted_source,
            "initial_origin_queue_veh":float((initial_origin_queue or {}).get(road,0)),
            "final_origin_queue_veh":state.mainline_origin_queue[road],"initial_n_veh":sum(n0),"final_n_veh":sum(after)})
        if self.literature is not None:
            details[-1]['literature_counts'] = literature_counts
        if route_initial is not None:
            details[-1]['route_inventory_initial'] = route_initial
            details[-1]['route_inventory_final'] = copy.deepcopy(state.offramp_route_inventory_state)
        if joint_lanes is not None:
            details[-1]['joint_lane_region'] = dict(rows=joint_lanes.rows, receiving_rows=joint_lanes.receiving_rows, junction_rows=joint_lanes.junction_rows, route_marginal_max_error=joint_lanes.max_residual, specification=route_lane_regions[road], full_runtime_qualified=False)
        if residence_audit:
            details[-1]['off_connector_residence_event_veh_h'] = sum(store.residence_veh_h for store in stores.values())
            details[-1]['off_connector_residence_by_port'] = {off:store.residence_veh_h for off,store in stores.items()}
        if ramp_buffers:
            residence_key = ('ramp_connector_residence_local_1s_veh_h' if local_ramp_step == 1.
                             else 'ramp_connector_residence_10s_veh_h')
            details[-1][residence_key] = sum(buffer.connector_ttt_veh_h for buffer in ramp_buffers.values())
            details[-1]['ramp_ttt_scope'] = ('Local1s interval-start connector stock only; upstream outside-component backlog excluded'
                if local_ramp_step == 1. else 'Interval-start connector stock only; upstream outside-component backlog excluded')
        if vsl_audit is not None:
            details[-1]['vsl_binding_audit'] = vsl_audit
        if lane_groups is not None:
            lane_group_results[road] = lane_groups.rows
            if lane_groups.port_response:
                details[-1]['port_response_trace']=lane_groups.port_response_rows
            if lane_groups.hadi_audit is not None:
                details[-1]['hadiuzzaman_audit']=lane_groups.hadi_audit
            details[-1]['lane_group_continuity_residual_max_veh'] = lane_groups.max_residual
            if lane_groups.partitions:
                details[-1]['branch_partition_continuity_residual_max_veh']=lane_groups.max_partition_residual
                details[-1]['branch_partition_trace']=lane_groups.partition_rows
            if lane_groups.upstream_off:
                details[-1]['first_exit_inventory']={'initial':lane_groups.intent_initial,
                    'admitted':lane_groups.intent_entered,'exited':lane_groups.intent_exited,
                    'remaining':{o:sum(map(sum,rows))+sum(lane_groups.off[o])
                                 for o,rows in lane_groups.upstream_off.items()},
                    'max_residual_veh':lane_groups.max_intent_residual}
            if lane_groups.exchange_model is not None:
                details[-1]['state_exchange_feature_values'] = lane_groups.exchange_model.feature_values
                details[-1]['state_exchange_clipped_feature_values'] = lane_groups.exchange_model.clipped_feature_values
    if any(not math.isfinite(row[key]) for row in cells for key in ("n_veh","v_kmh","rho_veh_per_km_lane")):
        raise ArithmeticError("Nonfinite canonical rollout")
    result = {"cells":cells,"flows":flows,"diagnostics":{"roads":details,"future_state_resets":0,"horizon_s":horizon_sec}}
    if port_dynamics:
        result['ports'] = port_rows
        result['diagnostics']['dynamic_off_storage'] = True
    if ramp_dynamics is not None:
        result['ramps'] = ramp_rows
        result['diagnostics']['dynamic_ramp_boundary'] = {
            'schema': 'physical-ramp-boundary/v1', 'metadata': ramp_metadata,
            'outside_backlog_scope': 'Outside this freeway/connector component; caller must assign its real upstream area and cost',
            'other_ramps': 'Existing external release boundaries unchanged',
        }
        if local_ramp_step == 1.:
            result['diagnostics']['dynamic_ramp_boundary'].update(
                local_step_sec=1., meter_cycle_sec=meter_cycle,
                receiving_rule='Canonical10s t-start receiving budget with uniform1s rate envelope',
                head_rule='Finite nominal post-head storage; preserve observed initial excess and block new head service until space opens')
            if tf!=10.:
                result['diagnostics']['dynamic_ramp_boundary']['receiving_rule']=f'Canonical{tf:g}s t-start receiving budget with uniform1s rate envelope'
                result['diagnostics']['component_integration_step_sec']=tf
    if vsl_zone_heads is not None:
        result['diagnostics']['explicit_vsl_zone_heads'] = copy.deepcopy(vsl_zone_heads)
    if lane_group_results:
        result['lane_groups'] = lane_group_results
        result['diagnostics']['lane_group_model'] = 'Candidate component model; no full-GNE integration'
    return result
